const D = { rate:.5, length:.5, density:.6, energy:.6, hue:220, speed:1, dir:35, x:.72, y:.22, style:'nightsky', act:'shower', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), lrp=(a,b,t)=>a+(b-a)*t, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360), st=P.style;
const sky=st==='nightsky', ink=st==='ink', blue=st==='blueprint', retro=st==='retro', irid=st==='iridescent';
const rate=clp(P.rate,0,1), len=clp(P.length,0,1), dens=clp(P.density,0,1), en=clp(P.energy,0,1)*(0.55+0.6*K.intensity), spd=P.speed;

// forced palettes per style
let starH=H, twk=1;
if(retro){ starH=130; } else if(blue){ starH=205; }

const oldOp=drawingContext.globalCompositeOperation;

// ---- persistent starfield (continuous drift + twinkle carries the motion floor) ----
const NS = Math.round(lrp(50,340,dens));
if(S.seedUsed!==P.seed || S.NS!==NS){
  S.seedUsed=P.seed; S.NS=NS; S.star=[];
  for(let i=0;i<NS;i++) S.star.push({ x:fr(i*1.7+1), y:fr(i*3.3+2), b:0.3+fr(i*5.1+3)*0.7,
    tw:0.4+fr(i*7.9+4)*2.6, ph:fr(i*2.3+5)*TAU, dep:0.3+fr(i*4.4+6)*0.7, hj:(fr(i*6.6+7)-0.5)*40 });
}
// slow parallax drift of the whole field — never re-phases
const driftX=K.t*u*0.004*spd, driftY=Math.sin(K.t*0.05)*u*0.01;
noStroke();
if(retro){ blendMode(BLEND); } else { blendMode(ADD); }
for(let i=0;i<NS;i++){
  const s2=S.star[i];
  const sx=md(s2.x*W - driftX*s2.dep, W);
  const sy=md(s2.y*Hh + driftY*s2.dep, Hh);
  const tw=0.45+0.55*Math.sin(K.t*s2.tw*(0.6+spd*0.5)+s2.ph);
  const sb=s2.b*(0.4+0.6*tw)*(0.7+A.treble*0.9);
  const sz=u*0.0035*(0.5+s2.b)*(0.7+0.6*tw)*(retro?1.4:1);
  let col;
  if(retro) col=[130,70,55+45*tw];
  else if(ink) col=[md(H,360),8,lrp(60,100,tw)];
  else if(blue) col=[205,50,lrp(55,100,tw)];
  else if(irid) col=[md(starH+s2.hj+K.t*8,360),55,100];
  else col=[md(starH+s2.hj,360),clp(35+s2.hj*0.5,0,60),100];
  fill(col[0],col[1],col[2], clp((sky?70:60)*sb,0,90));
  if(retro){ rect(sx,sy,sz*1.2,sz*1.2); } else { circle(sx,sy,sz); }
}
blendMode(BLEND);

// faint drifting nebula/aurora band (extra low-freq motion, keeps luminance alive)
blendMode(ADD); noStroke();
for(let b=0;b<3;b++){
  const by=Hh*(0.3+0.2*b)+u*0.05*Math.sin(K.t*(0.06+0.02*b)+b);
  const bh=u*(0.18+0.06*b);
  const ba=(sky||irid?5:3)*(0.6+0.4*Math.sin(K.t*0.07+b))*(0.7+en*0.4);
  const bc= irid?[md(starH+b*40+K.t*6,360),50,90]: ink?[md(H,360),6,80]: retro?[135,50,70]:[md(starH+b*20,360),40,85];
  fill(bc[0],bc[1],bc[2], clp(ba,0,10));
  ellipse(W*(0.3+0.2*b)+u*0.1*Math.sin(K.t*0.03+b), by, W*0.9, bh);
}
blendMode(BLEND);

// ---- meteors: time-slotted lanes, seed-deterministic, K.t-driven ----
const rad = P.dir*Math.PI/180;              // travel direction (deg from +x, downward positive)
const vx=Math.cos(rad), vy=Math.sin(rad);
const NL = Math.max(2, Math.round(lrp(2,7,rate)));     // concurrent lanes
const interval = lrp(6.5, 1.4, rate) / clp(spd,0.25,4); // seconds between a lane's meteors
const streakLen = u*lrp(0.10,0.62,len);
const radiantX=P.x*W, radiantY=P.y*Hh;

function drawMeteor(hx,hy,life,br,hj,seg){
  // life 0..1 across its flight; brightness fades near end
  const fade=clp(life*8,0,1)*clp((1-life)*3.5,0,1);
  if(fade<=0.01) return;
  const tlx=hx-vx*streakLen, tly=hy-vy*streakLen;
  if(blue){
    // schematic trajectory: dashed vector + radiant tick + arrowhead (abstract)
    stroke(205,55,100, 70*fade); strokeWeight(Math.max(1,u*0.0016));
    const dn=10; for(let d=0;d<dn;d++){ if(d%2) continue; const t0=d/dn,t1=(d+1)/dn;
      line(lrp(tlx,hx,t0),lrp(tly,hy,t0),lrp(tlx,hx,t1),lrp(tly,hy,t1)); }
    noStroke(); fill(205,60,100,90*fade); circle(hx,hy,u*0.01);
    // arrow head
    stroke(205,55,100,80*fade); const a=rad;
    line(hx,hy, hx-Math.cos(a-0.4)*u*0.02, hy-Math.sin(a-0.4)*u*0.02);
    line(hx,hy, hx-Math.cos(a+0.4)*u*0.02, hy-Math.sin(a+0.4)*u*0.02);
    return;
  }
  if(ink){
    // sumi splatter streak — tapered dry brush, ink droplets
    noStroke();
    for(let s2=0;s2<seg;s2++){ const f0=s2/seg; const px=lrp(tlx,hx,f0), py=lrp(tly,hy,f0);
      const w=u*0.006*(f0*f0)*(0.6+br); fill(md(H,360),10,lrp(30,10,f0), 70*fade*f0);
      ellipse(px,py,w*2.2,w*2.2); }
    fill(md(H,360),12,8, 80*fade); circle(hx,hy,u*0.012*(0.7+br));
    for(let k=0;k<3;k++){ if(fr(k+hj)>0.5){ const sp=fr(k*3+hj+1); fill(md(H,360),10,12,50*fade); circle(hx-vx*sp*u*0.04+ (fr(k)-0.5)*u*0.02, hy-vy*sp*u*0.04+(fr(k+2)-0.5)*u*0.02, u*0.004);} }
    return;
  }
  // nightsky / retro / iridescent: glowing additive trail + hot head
  blendMode(ADD); noStroke();
  for(let s2=0;s2<seg;s2++){ const f0=s2/seg;
    const px=lrp(tlx,hx,f0), py=lrp(tly,hy,f0);
    const w=u*0.007*(f0*f0*f0)*(0.7+br+0.5*en);
    let col;
    if(retro) col=[130,60,100];
    else if(irid) col=[md(starH+hj+f0*120+K.t*20,360),70,100];
    else col=[md(starH+hj+lrp(30,-20,f0),360), lrp(30,70,1-f0), 100];
    fill(col[0],col[1],col[2], clp(75*fade*f0*f0,0,90));
    ellipse(px,py,w*2,w*2);
  }
  // hot head w/ glow
  drawingContext.shadowBlur=u*0.02*(0.8+br); drawingContext.shadowColor= retro?'rgba(120,255,140,0.9)':'rgba(200,220,255,0.95)';
  const hc= retro?[125,25,100]: irid?[md(starH+K.t*20,360),40,100]:[md(starH+10,360),18,100];
  fill(hc[0],hc[1],hc[2], 95*fade); circle(hx,hy,u*0.014*(0.7+br+0.4*K.pulse));
  drawingContext.shadowBlur=0;
  blendMode(BLEND);
}

// act arcs
let burst=0, jitterA=1;
if(P.act==='sparse'){ /* fewer, wandering — handled by prob gate */ jitterA=1.6; }
else if(P.act==='storm'){ burst = (Math.sin(K.t*0.12)>0.6)?1:0; }

for(let ln=0;ln<NL;ln++){
  const slotT = K.t/interval + ln*0.618 + P.seed*0.13;
  const slot = Math.floor(slotT);
  const local = frc(slotT);                    // 0..1 within this slot
  const rnd = fr(slot*3.1 + ln*57.2 + 11);
  // presence probability (sparse act suppresses; storm bursts add)
  let prob = P.act==='sparse'? 0.35 : 0.72;
  if(P.act==='storm') prob = burst? 0.95 : 0.4;
  if(rnd > prob) continue;
  // meteor flight occupies first ~35% of the slot
  const flight = 0.35;
  if(local > flight) continue;
  const life = local/flight;                    // 0..1
  const hj=(fr(slot*7+ln*13+2)-0.5)*50;
  const br=0.5+fr(slot*11+ln*5+3)*0.9;
  // spawn spread around radiant, offset perpendicular to travel
  const perpX=-vy, perpY=vx;
  const spread=(fr(slot*5+ln*9+4)-0.5)*u*0.7*jitterA;
  const along=(fr(slot*2+ln*3+5)-0.5)*u*0.3;
  const startX=radiantX+perpX*spread+vx*along - vx*u*0.2;
  const startY=radiantY+perpY*spread+vy*along - vy*u*0.2;
  const travel=u*lrp(0.5,1.15,br);
  const hx=startX+vx*travel*life;
  const hy=startY+vy*travel*life;
  drawMeteor(hx,hy,life,br,hj, sky||irid||retro?9:7);
}

// radiant glow marker for nightsky/iridescent (subtle, breathes)
if((sky||irid) && P.act!=='sparse'){
  blendMode(ADD); noStroke();
  const rg=u*0.05*(0.8+0.3*K.swell);
  for(let r=3;r>0;r--){ const tt=r/3; fill(md(starH,360),30,100, 6*tt*(0.6+en*0.4)); ellipse(radiantX,radiantY,rg*tt*2,rg*tt*2); }
  blendMode(BLEND);
}

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.shadowBlur=0; noStroke();
